     "tema": "Características dos direitos da personalidade",
     "assertiva": "Com exceção dos casos previstos em lei, os direitos da personalidade são intransmissíveis e irrenunciáveis, não podendo o seu exercício sofrer limitação voluntária.",
     "gabarito": "C",
     "comentario": {
      "resumo": "Literalidade do art. 11: **intransmissíveis** e **irrenunciáveis**, ressalvados os casos legais.",
      "lei": [
       {
        "lei": "L10406",
        "art": "11",
        "par": "",
        "inc": "",
        "rotulo": "CC, art. 11",
        "texto": "Com exceção dos casos previstos em lei, os direitos da personalidade são intransmissíveis e irrenunciáveis, não podendo o seu exercício sofrer limitação voluntária."
       }
      ],
      "palavras_chave": [
       "direitos da personalidade",
       "intransmissíveis",
       "irrenunciáveis"
      ],
      "aprofundamento": "Os direitos da personalidade protegem atributos essenciais da pessoa: vida, corpo, nome, imagem, honra, privacidade. Como estão ligados à própria condição humana, não podem sair da esfera do titular: são **intransmissíveis** e **irrenunciáveis**, e o exercício não admite limitação voluntária.\n\nA ressalva \"com exceção dos casos previstos em lei\" é o que torna o sistema funcional. A pessoa pode ceder o uso da imagem por contrato, consentir em cirurgia ou doar órgão; o que não pode é abrir mão do direito em si. A doutrina majoritária admite limitações temporárias, específicas e que não firam a dignidade.\n\nA banca costuma retirar a ressalva legal, tornando a frase absoluta, ou afirmar que o direito pode ser renunciado por contrato. Disponível, em certa medida, é o exercício; o direito não.",
      "memorize": "Personalidade: intransmissível e irrenunciável, salvo casos legais; cede-se o uso, nunca o direito."
     }
