        "par": "",
        "inc": "",
        "rotulo": "CC, art. 1.260",
        "texto": "Aquele que possuir coisa móvel como sua, contínua e incontestadamente durante três anos, com justo título e boa-fé, adquirir-lhe-á a propriedade."
