      "aprofundamento": "Quando a lei brasileira deve produzir efeitos no exterior, como nas relações de brasileiros com a representação diplomática, o prazo de vacatio é maior. A razão é prática: a divulgação da lei fora do país é mais lenta, e o legislador concedeu tempo extra para que ela seja conhecida.\n\nA ressalva \"quando admitida\" também importa: a lei brasileira só tem obrigatoriedade no exterior nas hipóteses em que o direito internacional e o Estado estrangeiro a admitem.\n\nA assertiva transporta para o exterior o prazo interno. Não confunda os dois: no Brasil, o prazo é contado em dias; no exterior, em meses.",
      "memorize": "Vacatio: quarenta e cinco dias no Brasil; três meses no exterior."
