     "ponto": "DBA26-CIV-8",
     "tema": "Prazo para sanar o vício",
     "assertiva": "Não sendo o vício do produto sanado no prazo máximo de sessenta dias, pode o consumidor exigir a substituição do produto, a restituição imediata da quantia paga ou o abatimento proporcional do preço.",
     "gabarito": "E",
     "comentario": {
      "resumo": "Art. 18, § 1º: o prazo é de **trinta dias**. As partes podem convencionar entre 7 e 180 dias (§ 2º).",
      "lei": [
       {
        "lei": "L8078",
        "art": "18",
        "par": "",
        "inc": "",
        "rotulo": "CDC, art. 18, § 1º",
        "texto": "Não sendo o vício sanado no prazo máximo de trinta dias, pode o consumidor exigir, alternativamente e à sua escolha:\nI - a substituição do produto por outro da mesma espécie, em perfeitas condições de uso;\nII - a restituição imediata da quantia paga, monetariamente atualizada, sem prejuízo de eventuais perdas e danos;\nIII - o abatimento proporcional do preço."
       }
      ],
      "palavras_chave": [
       "vício do produto",
       "trinta dias"
      ],
      "correcao": {
       "erro": "Fixa em sessenta dias o prazo máximo para o fornecedor sanar o vício.",
       "certo": "Não sendo o vício sanado no prazo máximo de trinta dias, o consumidor pode exigir, à sua escolha, a substituição do produto, a restituição imediata da quantia paga ou o abatimento proporcional do preço."
      },
      "aprofundamento": "No **vício do produto**, o problema afeta a qualidade ou a quantidade do bem, tornando-o impróprio ou diminuindo seu valor, sem causar acidente. O CDC dá ao fornecedor uma oportunidade de sanar o vício, dentro de um prazo legal máximo.\n\nSe o vício não for sanado nesse prazo, o consumidor escolhe, à sua opção, entre três alternativas: substituição do produto, restituição da quantia paga atualizada, com eventuais perdas e danos, ou abatimento proporcional do preço. A escolha é dele, e não do fornecedor.\n\nAs partes podem convencionar prazo diferente, dentro dos limites legais de sete a cento e oitenta dias. A banca dobra o prazo, como nesta assertiva, ou transfere a escolha ao fornecedor.",
      "memorize": "Vício do produto: trinta dias para sanar; depois, escolha do consumidor (substituir, restituir, abater)."
     }
