     "gabarito": "C",
     "comentario": {
      "resumo": "Art. 49: **7 dias**, contratação **fora do estabelecimento**; os valores pagos são devolvidos de imediato, monetariamente atualizados.",
      "lei": [
       {
        "lei": "L8078",
        "art": "49",
        "par": "",
        "inc": "",
        "rotulo": "CDC, art. 49",
        "texto": "O consumidor pode desistir do contrato, no prazo de 7 dias a contar de sua assinatura ou do ato de recebimento do produto ou serviço, sempre que a contratação de fornecimento de produtos e serviços ocorrer fora do estabelecimento comercial, especialmente por telefone ou a domicílio."
       }
      ],
      "palavras_chave": [
       "arrependimento",
       "sete dias"
      ],
      "aprofundamento": "O **direito de arrependimento** protege o consumidor que contrata fora do estabelecimento comercial, por telefone, a domicílio ou pela internet. Nessas situações ele não pode ver, tocar ou experimentar o produto, e muitas vezes é surpreendido pela abordagem, sem tempo de refletir.\n\nO direito é **potestativo** e imotivado: o consumidor não precisa justificar a desistência nem provar defeito. Exercido no prazo, os valores pagos são devolvidos de imediato e atualizados, e o fornecedor arca com o risco da venda a distância.\n\nO prazo corre da assinatura ou do recebimento do produto ou serviço. A banca costuma estender o direito às compras feitas na loja física, ou exigir motivo para a desistência.",
      "exemplo": "Vera compra um liquidificador pela internet, recebe-o e se arrepende no dia seguinte. Pode desistir sem justificar e receber de volta tudo o que pagou, atualizado.",
      "memorize": "Arrependimento: 7 dias, só fora do estabelecimento, sem justificar, com devolução imediata."
     }
