     "assertiva": "O credor titular da posição de proprietário fiduciário de bens móveis ou imóveis não se submete aos efeitos da recuperação judicial, prevalecendo os direitos de propriedade sobre a coisa.",
     "gabarito": "C",
     "comentario": {
      "resumo": "Art. 49, § 3º: a **alienação fiduciária** fica fora (a \"trava bancária\"), mas não se permite, no stay period, a retirada de **bens de capital essenciais**.",
      "lei": [
       {
        "lei": "L11101",
        "art": "49",
        "par": "",
        "inc": "",
        "rotulo": "Lei 11.101/2005, art. 49, § 3º",
        "texto": "Tratando-se de credor titular da posição de proprietário fiduciário de bens móveis ou imóveis, de arrendador mercantil, de proprietário ou promitente vendedor de imóvel cujos respectivos contratos contenham cláusula de irrevogabilidade ou irretratabilidade, inclusive em incorporações imobiliárias, ou de proprietário em contrato de venda com reserva de domínio, seu crédito não se submeterá aos efeitos da recuperação judicial e prevalecerão os direitos de propriedade sobre a coisa e as condições contratuais, observada a legislação respectiva, não se permitindo, contudo, durante o prazo de suspensão a que se refere o § 4º do art. 6º desta Lei, a venda ou a retirada do estabelecimento do devedor dos bens de capital essenciais a sua atividade empresarial."
       }
      ],
      "palavras_chave": [
       "proprietário fiduciário",
       "bens de capital essenciais"
      ],
      "aprofundamento": "O credor que é **proprietário fiduciário**, como o banco em contrato de alienação fiduciária, não se submete aos efeitos da recuperação. O fundamento é que o bem não pertence ao devedor, mas ao credor, que tem direito de propriedade, e o plano não pode dispor do que não é do devedor. A prática ficou conhecida como trava bancária.\n\nA lei, porém, impõe um limite durante o stay period: o credor não pode vender nem retirar do estabelecimento os **bens de capital essenciais** à atividade empresarial. Sem as máquinas que produzem, a empresa não teria como se recuperar.\n\nA banca costuma submeter o fiduciário ao plano ou permitir a retirada imediata de bens essenciais. A exclusão do crédito convive com a proteção temporária da atividade.",
      "memorize": "Fiduciário fora da recuperação, mas não retira bens de capital essenciais durante o stay period."
     }
