      "aprofundamento": "A **impontualidade** é a hipótese mais comum de pedido de falência: o devedor não paga, sem relevante razão de direito, obrigação líquida materializada em título executivo protestado. O protesto comprova a mora de forma pública, e o valor mínimo evita que a falência seja usada como meio de cobrança de pequenas dívidas.\n\nO piso é medido na **data do pedido**, e os credores podem reunir-se em litisconsórcio para alcançá-lo, somando seus créditos. A expressão \"sem relevante razão de direito\" permite ao devedor defender-se demonstrando, por exemplo, que a dívida é indevida.\n\nA assertiva eleva o valor do piso. A banca costuma alterar o número ou dispensar o protesto.",
