      "aprofundamento": "Na assembleia-geral, os credores são divididos em classes para que interesses semelhantes votem juntos. O trabalhista vota na sua classe com **o total do crédito, independentemente do valor**. O teto de salários mínimos por credor é regra de classificação para pagamento na **falência**, e não regra de voto na recuperação.\n\nQuem tem o voto dividido é o credor com **garantia real**: vota na classe própria até o valor do bem e, pelo restante, na classe dos quirografários. A lógica é que, acima do valor da garantia, ele está na mesma situação de qualquer credor sem garantia.\n\nA pegadinha transplanta o teto da classificação falimentar para a assembleia. Separe sempre os dois momentos: pagar na falência e votar na recuperação.",
